'use strict';
labels.crm='CRM';accessModules.push('crm');accessParents.crm='clientes';
auditNav[0][1].splice(4,0,['crm','users']);
const crmState={tab:'overview',query:'',page:0,status:'pending',customerId:'',payload:null};
const crmDate=v=>v?fmtDate(v):'Sin registrar';
const crmStatus={pending:'Pendiente',done:'Completada',cancelled:'Cancelada'};
function crmAction(text,action,style=''){return button(text,'x-crm-'+action,style);}
function crmTabs(){return `<div class="crm-tabs" role="group" aria-label="Secciones del CRM">${[['overview','Resumen'],['customers','Clientes'],['agenda','Agenda']].map(([id,label])=>`<button class="btn ${crmState.tab===id?'primary':''}" data-action="x-crm-tab-${id}" aria-pressed="${crmState.tab===id}">${label}</button>`).join('')}</div>`;}
extraUI.views.crm=function(){return heading('Cada cliente, una relación que cuidar.','Tu agenda comercial, el contexto del cliente y la próxima acción en un solo lugar.',`<span class="crm-beta">Beta</span>`)+`<div class="crm-intro"><div>${icon('users',20)}<span><strong>CRM de Áurea</strong><small>Beta · relación comercial, posventa, campañas y comunicaciones.</small></span></div><p>Las ventas y los saldos siguen en sus módulos de origen. Aquí organizas el seguimiento.</p></div>${crmTabs()}<div id="crm-content" aria-live="polite"><section class="card card-body">Cargando tu espacio comercial…</section></div>`;};
function crmPager(total){return total>25?`<div class="row between crm-pager"><span class="muted">Página ${crmState.page+1} · ${total} registros</span><div class="row">${crmState.page?crmAction('Anterior','prev'):''}${(crmState.page+1)*25<total?crmAction('Siguiente','next'):''}</div></div>`:'';}
function crmTaskRows(tasks){return tasks.length?table(['Actividad / cliente','Fecha','Responsable','Estado',''],tasks.map(t=>`<tr><td><strong>${esc(t.title)}</strong><small>${esc(t.customer||'')} · ${esc(t.type)}</small></td><td>${crmDate(t.dueDate)} ${t.status==='pending'&&t.dueDate<appState.today?badge('Vencida','warn'):''}</td><td>${esc(t.owner||'')}</td><td>${esc(crmStatus[t.status])}</td><td>${crmAction('Ver ficha','client-'+t.customerId,'text')}${allowed('crm','editar')&&t.status==='pending'?crmAction('Completar','complete-'+t.id,'text'):''}</td></tr>`)):empty('Tu agenda está despejada.','Abre la ficha de un cliente para programar su próxima actividad.');}
function crmOverview(r){const a=r.summary;return `<div class="kpis crm-kpis">${kpi('Clientes en tu espacio',a.customers,'Usan el directorio de Áurea',true)+kpi('Para hoy',a.today,'Actividades pendientes')+kpi('Vencidas',a.overdue,'Requieren seguimiento')+kpi('Por realizar',a.pending,'Próximas acciones')}</div><section class="card"><div class="card-head"><div><h2>Tu siguiente paso</h2><small>Prioriza lo pendiente y conserva el contexto de cada cliente.</small></div>${crmAction('Ver clientes','tab-customers','primary')}</div>${crmTaskRows(r.tasks.slice(0,8))}</section>${r.manager&&a.unassigned?`<div class="info-strip crm-spacing">${a.unassigned} clientes sin responsable. Puedes asignarlos desde su ficha comercial.</div>`:''}<section class="card card-body crm-roadmap"><span class="crm-beta">Beta · en desarrollo</span><h2>Crecer con orden.</h2><p>Ya disponibles: ficha comercial, responsables, notas, agenda, oportunidades, cotizaciones, preparación de ventas y seguimiento interno de posventa, segmentos dinámicos y campañas manuales.</p><p class="muted">Comunicaciones y calendario disponibles en Beta. La activación de proveedores requiere tus cuentas y configuración.</p></section>`;}
function crmCustomers(r){return `<section class="card"><div class="card-head"><div><h2>Clientes, sin duplicar registros.</h2><small>${r.manager?'Directorio compartido con Clientes y cartera.':'Clientes asignados a tu cuenta.'}</small></div>${allowed('clientes','crear')?button('Registrar cliente','customer-new','primary','plus'):''}</div><form id="crm-search" class="crm-search"><label class="search">${icon('search')}<input name="query" value="${esc(crmState.query)}" placeholder="Nombre, documento, teléfono o etiqueta" aria-label="Buscar clientes en CRM"></label>${submit('Buscar')}</form>${r.customers.length?table(['Cliente','Contacto','Responsable','Etiquetas',''],r.customers.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.doc||'Sin documento')} ${c.active===false?'· Inactivo':''}</small></td><td>${esc(c.phone||'Sin teléfono')}<small>${esc(c.email||'')}</small></td><td>${esc(c.owner)}</td><td>${c.profile.tags.map(t=>badge(t)).join(' ')||'—'}</td><td>${crmAction('Abrir ficha','client-'+c.id,'text')}</td></tr>`)):empty('No encontramos clientes.','Revisa la búsqueda o solicita que te asignen clientes para comenzar.')}</section>${crmPager(r.total)}`;}
function crmAgenda(r){return `<section class="card"><div class="card-head"><div><h2>Agenda comercial</h2><small>La persona responsable se toma de la ficha del cliente.</small></div><form id="crm-agenda-filter" class="row">${select('Mostrar actividades','status',[['pending','Pendientes'],['done','Completadas'],['cancelled','Canceladas'],['all','Todas']],crmState.status)}${submit('Consultar')}</form></div>${crmTaskRows(r.tasks)}</section>${crmPager(r.taskTotal)}`;}
function crmDetail(r){const c=r.detail,p=c.profile;return `<div class="row between crm-spacing">${crmAction('Volver a clientes','tab-customers','text')}<span class="muted">Ficha única · ${esc(c.name)}</span></div><div class="crm-detail-grid"><section class="card"><div class="card-head"><div><h2>${esc(c.name)}</h2><small>${esc(c.doc||'Sin documento')}</small></div>${allowed('clientes','editar')?button('Editar contacto','customer-edit-'+c.id,'text'):''}</div><div class="card-body"><dl class="crm-facts"><div><dt>Teléfono</dt><dd>${esc(c.phone||'Sin registrar')}</dd></div><div><dt>Correo</dt><dd>${esc(c.email||'Sin registrar')}</dd></div><div><dt>Responsable</dt><dd>${esc(c.owner)}</dd></div><div><dt>Canal preferido</dt><dd>${esc(({unknown:'Sin registrar',phone:'Llamada',whatsapp:'WhatsApp',email:'Correo'})[p.channel])}</dd></div><div><dt>Contacto comercial autorizado</dt><dd>${esc(({unknown:'Sin registrar',yes:'Sí · registrado manualmente',no:'No contactar con fines comerciales'})[p.consent])}</dd></div><div><dt>Fecha de nacimiento</dt><dd>${crmDate(p.birthday)}</dd></div></dl><div class="row">${p.tags.map(t=>badge(t)).join('')}</div><p class="crm-text">${esc(p.preferences||'Añade tallas, preferencias y contexto útil para atender a este cliente.')}</p>${allowed('crm','editar')?crmAction('Editar ficha comercial','profile','primary'):''}</div></section><section class="card"><div class="card-head"><h2>Su relación con tu joyería</h2></div><div class="card-body"><dl class="crm-facts">${c.purchases?`<div><dt>Ventas registradas</dt><dd>${c.purchases.count}</dd></div><div><dt>Valor de ventas</dt><dd>${money(c.purchases.total)}</dd></div><div><dt>Última venta</dt><dd>${crmDate(c.purchases.last)}</dd></div>`:'<p class="muted">No tienes acceso al historial de ventas.</p>'}${c.debt!==undefined?`<div><dt>Saldo actual</dt><dd>${money(c.debt)}</dd></div>`:''}</dl><p class="muted crm-text">Información consultada desde Ventas y Cartera. Incluye únicamente las operaciones disponibles en Áurea.</p><p class="muted crm-text">La ficha comercial no genera ventas, reservas ni movimientos de dinero.</p></div></section></div><section class="card crm-spacing"><div class="card-head"><h2>Próximas acciones</h2>${allowed('crm','crear')?crmAction('Programar actividad','task-new','primary'):''}</div>${c.tasks.length?table(['Actividad','Fecha','Estado',''],c.tasks.map(t=>`<tr><td><strong>${esc(t.title)}</strong><small>${esc(t.type)} · ${esc(t.description||'')}</small>${t.outcome?`<small>Resultado: ${esc(t.outcome)}</small>`:''}</td><td>${crmDate(t.dueDate)}</td><td>${esc(crmStatus[t.status])}</td><td>${allowed('crm','editar')?(t.status==='pending'?crmAction('Completar','complete-'+t.id,'text')+crmAction('Editar','task-edit-'+t.id,'text'):crmAction('Reabrir','reopen-'+t.id,'text')):''}${t.status==='pending'&&allowed('crm','eliminar')?crmAction('Cancelar','cancel-'+t.id,'text'):''}</td></tr>`)):empty('Define la próxima acción.','Programa una llamada, cita, cobranza o contacto de posventa.')}</section><div class="crm-detail-grid crm-spacing"><section class="card"><div class="card-head"><h2>Notas del cliente</h2>${allowed('crm','crear')?crmAction('Añadir nota','note','primary'):''}</div><div class="card-body">${c.notes.length?c.notes.map(n=>`<article class="crm-entry"><p>${esc(n.text)}</p><small>${esc(n.author)} · ${crmDate(n.createdAt)}</small></article>`).join(''):empty('Todo empieza con escuchar.','Registra contexto útil y resultados de tus conversaciones.')}</div></section><section class="card"><div class="card-head"><h2>Historial reciente de seguimiento</h2></div><div class="card-body">${c.events.length?c.events.map(e=>`<article class="crm-entry"><p>${esc(e.label)}</p><small>${esc(e.author)} · ${crmDate(e.createdAt)}</small></article>`).join(''):'<p class="muted">Las asignaciones y actividades quedarán registradas aquí.</p>'}</div></section></div>`;}
async function loadCrm(){const target=document.querySelector('#crm-content');if(!target)return;try{const q={query:crmState.query,page:crmState.page,status:crmState.tab==='overview'?'pending':crmState.status,...(crmState.tab==='detail'?{customerId:crmState.customerId}:{})},r=await api('/api/crm?'+new URLSearchParams(q));if(!target.isConnected)return;crmState.payload=r;target.innerHTML=crmState.tab==='detail'?crmDetail(r):crmState.tab==='customers'?crmCustomers(r):crmState.tab==='agenda'?crmAgenda(r):crmOverview(r);}catch(e){if(target.isConnected)target.innerHTML=empty('No pudimos abrir el CRM.',e.message,crmAction('Reintentar','retry'));}}
const crmDecorate=extraUI.decorate;extraUI.decorate=function(){crmDecorate();const link=document.querySelector('.sidebar a[href="#crm"]');if(link){link.insertAdjacentHTML('beforeend','<span class="crm-beta">Beta</span>');if(appState.route==='crm')link.setAttribute('aria-current','page');}if(appState.route==='crm')loadCrm();};
function crmProfileForm(){const r=crmState.payload,c=r.detail,p=c.profile;modal('Ficha comercial · '+c.name,pForm('crm-profile-form',(r.manager?select('Responsable del cliente','ownerId',[['','Sin asignar'],...r.members.map(m=>[m.id,m.name])],p.ownerId):'')+input('Etiquetas separadas por comas','tags',p.tags.join(', '),'text','maxlength="300"')+input('Fecha de nacimiento (opcional)','birthday',p.birthday||'','date')+select('Canal preferido','channel',[['unknown','Sin registrar'],['phone','Llamada'],['whatsapp','WhatsApp'],['email','Correo']],p.channel)+select('Autorización para contacto comercial','consent',[['unknown','Sin registrar'],['yes','Sí, autorización obtenida'],['no','No contactar con fines comerciales']],p.consent)+`<label class="field"><span>Preferencias y contexto</span><textarea name="preferences" rows="4" maxlength="1000">${esc(p.preferences||'')}</textarea></label><p class="muted">Registra autorización solo si la obtuviste del cliente. Los mensajes se preparan y confirman por separado en Comunicaciones.</p>`,'Guardar ficha',`data-customer="${esc(c.id)}"`));}
function crmTaskForm(id){const c=crmState.payload.detail,t=c.tasks.find(t=>t.id===id);modal(t?'Editar actividad':'Programar próxima acción',pForm('crm-task-form',input('Actividad','title',t?.title||'','text','required maxlength="140"')+select('Tipo','type',['Seguimiento','Llamada','Cita','Cobranza','Posventa'],t?.type||'Seguimiento')+input('Fecha de seguimiento','dueDate',t?.dueDate||appState.today,'date','required')+`<label class="field"><span>Detalles</span><textarea name="description" rows="3" maxlength="1000">${esc(t?.description||'')}</textarea></label><p class="muted">Responsable: ${esc(c.owner)}. Se actualiza desde la ficha del cliente.</p>`,'Guardar actividad',`data-customer="${esc(c.id)}" data-id="${esc(t?.id||'')}"`));}
function crmStatusForm(id,status){const r=crmState.payload,t=(r.detail?.tasks||r.tasks).find(t=>t.id===id);if(!t)return;modal(({done:'Completar actividad',pending:'Reabrir actividad',cancelled:'Cancelar actividad'})[status],pForm('crm-status-form',`<p>${esc(t.title)}</p><label class="field"><span>${status==='done'?'Resultado del seguimiento':'Motivo'}</span><textarea name="outcome" rows="4" maxlength="1000" required></textarea></label>`,'Guardar seguimiento',`data-id="${esc(id)}" data-status="${status}" data-customer="${esc(t.customerId)}"`));}
const crmPreviousAction=extraUI.action;extraUI.action=async function(a,t){if(!a.startsWith('x-crm-'))return crmPreviousAction(a,t);const action=a.slice(6);if(action.startsWith('tab-')){crmState.tab=action.slice(4);crmState.page=0;crmState.customerId='';render();return;}if(action.startsWith('client-')){crmState.customerId=action.slice(7);crmState.tab='detail';render();return;}if(action==='retry')return loadCrm();if(action==='prev'||action==='next'){crmState.page=Math.max(0,crmState.page+(action==='next'?1:-1));render();return;}if(action==='profile')return crmProfileForm();if(action==='task-new'||action.startsWith('task-edit-'))return crmTaskForm(action==='task-new'?'':action.slice(10));if(action==='note'){const c=crmState.payload.detail;return modal('Nota · '+c.name,pForm('crm-note-form','<label class="field"><span>Nota de seguimiento</span><textarea name="text" rows="5" maxlength="2000" required></textarea></label><p class="muted">Se conservarán el autor y la fecha. Las notas guardadas no se sobrescriben.</p>','Guardar nota',`data-customer="${esc(c.id)}"`));}for(const [prefix,status]of [['complete-','done'],['reopen-','pending'],['cancel-','cancelled']])if(action.startsWith(prefix))return crmStatusForm(action.slice(prefix.length),status);};
const crmPreviousSubmit=extraUI.submit;extraUI.submit=async function(form,v){if(form.id==='crm-search'){crmState.query=v.query;crmState.page=0;render();return null;}if(form.id==='crm-agenda-filter'){crmState.status=v.status;crmState.page=0;render();return null;}if(!form.id.startsWith('crm-'))return crmPreviousSubmit(form,v);const body={...v,customerId:form.dataset.customer},commands={'crm-profile-form':'crm.profile.save','crm-note-form':'crm.note.add','crm-task-form':'crm.task.save','crm-status-form':'crm.task.status'};if(form.dataset.id)body.id=form.dataset.id;if(form.dataset.status)body.status=form.dataset.status;return {command:commands[form.id],body};};
